"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["31072"],{13184(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>c,contentTitle:()=>o,toc:()=>h,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-participant-search","title":"Submit the participant search","description":"Reads a participant\'s full registry record by participant_code, including roles, status, encryption_cert and endpoint_URL.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-participant-search.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-participant-search","permalink":"/docs/pr-49/docs/nhcx/v1/api/registry/endpoints/registry-participant-search","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the participant search","sidebar_label":"Submit the participant search","sidebar_class_name":"api-method api-method--post","description":"Reads a participant\'s full registry record by participant_code, including roles, status, encryption_cert and endpoint_URL.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Submit the participant certificate and bridge update (v2)","permalink":"/docs/pr-49/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-update"},"next":{"title":"Submit the participant details (v2 search)","permalink":"/docs/pr-49/docs/nhcx/v1/api/registry/endpoints/registry-participant-details"}}'),i=a(62540),r=a(43023),s=a(52563),p=JSON.parse('{"id":"registry_participant_search","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/participant/search","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Participant search","title":"Submit the participant search","description":"Reads a participant\'s full registry record by participant_code, including roles, status, encryption_cert and endpoint_URL.\\n\\n### Business purpose\\n\\nBefore addressing a transaction to a counterparty, an integrator needs to know that the participant exists, is active, holds the expected role and publishes an encryption certificate and callback endpoint. The registry is the phone book of NHCX, and this call is the direct lookup by code. Providers use it to inspect a payer they have selected; payers use it to confirm the sender of an inbound request; everyone uses it to verify their own record after an update.\\n\\n### When to use\\n\\nUse it to check a participant\'s record once you know its code. Call it before you send the first message to a new recipient, or to confirm your own record after an update.\\n\\n### Preconditions\\n\\n- You have a valid access token in the `bearer_auth` header.\\n- You have the target\'s `participant_code`, the same value you will put in `x-hcx-recipient_code`.\\n\\n### Postconditions\\n\\nYou get the participant\'s full registry record. Nothing changes, and an unknown code returns `404`.\\n\\n### Common mistakes\\n\\n- Sending the code under a field name other than `participant_code`.\\n- Assuming a record means the participant can transact: its status must be active.\\n- Reading `encryption_cert` as the certificate itself. Use `/fetch/certs` for that.\\n- Leaving out the `Accept` header.\\n\\n### Best practices\\n\\n- Cache the record for the session and re-read it when a transport error (NHCX-1001) or decrypt failure (PAYR-1001/PAYR-1002) suggests stale routing or key data.\\n- Check roles and status before selecting the counterparty for x-hcx-recipient_code.\\n- Call it against your own code after every registry update to confirm the change is live.\\n- Never log payment_details from the response.\\n- Treat the participants array as possibly empty and handle 404 gracefully.\\n\\n### Related scenario\\n\\nA hospital\'s TPA desk has selected a payer code from /fetch/participants/list for a PMJAY patient. Before submitting anything the integration calls /participant/search with that participant_code and receives the payer\'s record: roles include payer, status is Active, scheme_code matches, and endpoint_URL and encryption_cert are populated. The engine stores the code as the payerId that will become x-hcx-recipient_code, calls /fetch/certs to obtain the actual certificate, and then encrypts and sends /v1/coverageeligibility/check.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[{"name":"Accept","required":true,"description":"Always `application/json` on the participant service.","example":"application/json","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"participant_code","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"participant_code":"<payer participant code>"},"responses":[{"status":"200","description":"HTTP 200 with ParticipantSearchResponse: timestamp (Unix timestamp when the request is sent) and participants, an array of full participant records with participant_code, linked_registry_codes, participant_name, scheme_code, roles, address, primaryEmail, additionalEmail, phone, primaryMobile, additionalMobile, status, signing_cert_path, encryption_cert, endpoint_url and payment_details.","example":{"timestamp":1716204567358,"participants":[{"participant_code":"<payer participant code>","participant_name":"Demo Insurance Company","linked_registry_codes":["125@payer"],"scheme_code":"default","roles":["payer"],"status":["Active"],"primaryEmail":"claims@demoinsurer.example.in","primaryMobile":"9800000001","encryption_cert":"https://registry.example.in/certs/1518.pem","endpoint_url":"https://nhcx.demoinsurer.example.in"}]},"synthesised":false,"fields":[{"name":"timestamp","type":"integer","required":false,"description":""},{"name":"participants","type":"object[]","required":false,"description":""},{"name":"participants.participant_code","type":"string","required":false,"description":""},{"name":"participants.participant_name","type":"string","required":false,"description":""},{"name":"participants.linked_registry_codes","type":"string[]","required":false,"description":""},{"name":"participants.scheme_code","type":"string","required":false,"description":""},{"name":"participants.roles","type":"string[]","required":false,"description":""},{"name":"participants.status","type":"string[]","required":false,"description":""},{"name":"participants.primaryEmail","type":"string","required":false,"description":""},{"name":"participants.primaryMobile","type":"string","required":false,"description":""},{"name":"participants.encryption_cert","type":"string","required":false,"description":""},{"name":"participants.endpoint_url","type":"string","required":false,"description":""}]}],"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participant_code\\": \\"<payer participant code>\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participant_code\\": \\"<payer participant code>\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Accept\\": \\"application/json\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"participant_code\\": \\"<payer participant code>\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Accept\\": \\"application/json\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"participant_code\\": \\"<payer participant code>\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Accept\\", \\"application/json\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"participant_code\\": \\"<payer participant code>\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Accept: application/json\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"participant_code\\": \\"<payer participant code>\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"participant_code\\": \\"<payer participant code>\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Accept\\", \\"application/json\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"Accept\\", \\"application/json\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"participant_code\\": \\"<payer participant code>\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Accept\'] = \'application/json\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"participant_code\\": \\"<payer participant code>\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let c={title:"Submit the participant search",sidebar_label:"Submit the participant search",sidebar_class_name:"api-method api-method--post",description:"Reads a participant's full registry record by participant_code, including roles, status, encryption_cert and endpoint_URL.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},o,d={},h=[];function l(e){return(0,i.jsx)(s.Ay,{operation:p})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}}}]);